type BlueprintRole = { phase:"now"|"next"|"later";department:string;title:string;headcount:number;professions:string[];requiredSkills:string[];usefulSkills:string[];criticality:"critical"|"important"|"useful";reason:string;workMode:"remote"|"hybrid"|"in_person" };
type BlueprintRecord = { id:string;outcome:string;assumptions:string[];coveredContributions:Array<{area:string;evidence:string}>;milestones:Array<{title:string;phase:string}>;gaps:string[];risks:string[];roles:BlueprintRole[];provider:string;usedFallback?:boolean;failureStatus?:string|null };
type ProfileRecord = { id:string;name:string|null;image:string|null;coverImage?:string|null;profession:string|null;headline:string|null;bio:string|null;industry:string|null;rankedSkills:string[];interests:string[];location:string|null;isN2Admin:boolean;isDemo?:boolean;isCurrent:boolean;projectCount:number;involvedCount:number;career:Array<{id:string;title:string;company:string;location:string|null;startDate:string|null;endDate:string|null;current:boolean;description:string|null}>;education:Array<{id:string;institution:string;qualification:string;fieldOfStudy:string|null;startYear:number|null;endYear:number|null;description:string|null}> };
type NotificationRecord = { id:string; type:string; title:string; body:string; href?:string|null; readAt?:string|null; createdAt:string; actorName?:string|null; actorImage?:string|null };
type TimelinePost = { id:string;body:string;attachmentType?:"image"|"video"|null;attachmentUrl?:string|null;videoUrl?:string|null;createdAt:string;authorId:string;authorName:string|null;authorImage:string|null;authorProfession?:string|null;authorIsAdmin?:boolean;isDemo?:boolean;linkedProjects:Array<{id:string;title:string}> };
type PulseSlide = {id:string;kind:string;label:string;value:string;title:string;detail:string;progress:number;projectId?:string};
type FeedFilterState = { industry:string;stage:string;workMode:string;location:string };

