  useEffect(()=>{if(!selected||!draft.trim())return;const ping=()=>fetch(`/api/conversations/${selected.id}/typing`,{method:"POST"}).catch(()=>undefined);ping();const timer=setInterval(ping,3000);return()=>clearInterval(timer)},[selected,draft]);
  useEffect(()=>{const timer=setTimeout(()=>{if(memberSearch.trim().length<2){setMemberResults([]);return}fetch(`/api/search?q=${encodeURIComponent(memberSearch)}`).then(r=>r.ok?r.json():{people:[]}).then(data=>setMemberResults(data.people??[]))},250);return()=>clearTimeout(timer)},[memberSearch]);
  async function send(type:"message"|"nudge"="message"){if(!selected||(!draft.trim()&&!attachment&&type==="message"))return;const response=await fetch(`/api/conversations/${selected.id}/messages`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({body:draft,attachmentType:attachment?.type,attachmentUrl:attachment?.url,type})});if(response.ok){setDraft("");setAttachment(null);const data=await response.json();setMessagesList(rows=>[...rows,{...data,senderId:currentMember.id??"",senderName:currentMember.name,senderImage:currentMember.img,status:"visible"}])}}
  async function conversationAction(action:"archive"|"restore"|"snooze"|"delete"){if(!selected)return;await fetch("/api/conversations",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({conversationId:selected.id,action,until:action==="snooze"?new Date(Date.now()+86400000).toISOString():undefined})});setSelected(null);load()}
  async function createConversation(){const response=await fetch("/api/conversations",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({recipientIds:chosen,name:chosen.length>1?groupName||"New group":undefined})});if(response.ok){setCompose(false);setChosen([]);setGroupName("");await load()}}
