  async function addMeet(event:FormEvent<HTMLFormElement>){event.preventDefault();setError("");const data=new FormData(event.currentTarget),start=new Date(String(data.get("startsAt"))),duration=Number(data.get("duration")),attendees=String(data.get("attendees")??"").split(",").map(email=>email.trim()).filter(Boolean).map(email=>({email}));const response=await fetch("/api/calendar/events",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({provider:data.get("provider"),title:data.get("title"),description:data.get("description"),startsAt:start.toISOString(),endsAt:new Date(start.getTime()+duration*60000).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,location:data.get("location")||undefined,attendees,online:data.get("provider")!=="in_person"})});const result=await response.json();if(!response.ok){setError(result.error??"Could not create the meet");return}setCreate(false);setDetail(result);load()}
